settings.liquid:
{%- comment -%}
  Presentation layer for the fish-temperature guide.

  The guide lives in page.body as ~4,000 words of WYSIWYG HTML — floated 480px
  images with inline margins, a wide unstyled table, two YouTube embeds, and
  anchor links. It is the SEO asset and is NOT edited here; this styles what it
  renders into (.page.rte) and adds a sticky route to the offer, because on a
  page this long an offer stack at the foot is one almost nobody reaches.
{%- endcomment -%}

<style>
  /* ---- readable measure, but let wide things breathe ------------------ */
  .page.rte { font-size: 17px; line-height: 1.7; color: #2b2b2b; }
  .page.rte > h2,
  .page.rte > h3,
  .page.rte > h4,
  .page.rte > p,
  .page.rte > ul,
  .page.rte > ol { max-width: 68ch; }

  /* ---- hierarchy: the WYSIWYG gives h2/h3/h4 no rhythm ---------------- */
  .page.rte h2 { font-size: clamp(25px, 3.1vw, 34px); line-height: 1.2; margin: 2.2em 0 .6em; }
  .page.rte h3 { font-size: clamp(20px, 2.3vw, 25px); line-height: 1.25; margin: 1.9em 0 .5em; }
  .page.rte h4 { font-size: 18px; line-height: 1.3; margin: 1.5em 0 .35em; font-weight: 600; }
  .page.rte h2:empty, .page.rte h3:empty, .page.rte p:empty { display: none; margin: 0; }
  .page.rte hr { margin: 2.6em 0; border: 0; border-top: 1px solid #e5e2dc; max-width: 68ch; }

  /* ---- images: the floats collapse badly on narrow screens ------------ */
  .page.rte img { border-radius: 12px; height: auto; }
  .page.rte h2 > span > img { display: block; margin: 0 auto; max-width: 100%; }
  @media (max-width: 749px) {
    .page.rte img { float: none !important; margin: 18px auto !important; display: block; }
  }

  /* ---- the temperature table is what people came for ------------------ */
  .page.rte table {
    width: 100%; border-collapse: collapse; margin: 1.6em 0;
    font-size: 15px; background: #fff;
    border: 1px solid #e5e2dc; border-radius: 12px; overflow: hidden;
  }
  .page.rte table td { border: 1px solid #e5e2dc !important; padding: 14px 16px !important; vertical-align: top; }
  .page.rte table tr:first-child td { background: #1D3D3E !important; }
  .page.rte table tr:first-child h5 span { color: #fff !important; font-weight: 600 !important; font-size: 14px !important; }
  .page.rte table tr:nth-child(even) td { background: #faf8f4; }
  .page.rte table p { margin: 0 0 .5em; max-width: none; }
  .page.rte table a { color: #1D3D3E; text-underline-offset: 2px; }
  /* horizontal scroll rather than a squashed table */
  .page.rte .sea-table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; margin: 1.6em 0; }
  .page.rte .sea-table-scroll > table { margin: 0; min-width: 680px; }

  /* ---- the anchor list is a jump nav; make it look like one ----------- */
  .page.rte ul.sea-jump {
    list-style: none; padding: 18px 20px; margin: 1.8em 0; max-width: 68ch;
    background: #faf8f4; border: 1px solid #e5e2dc; border-radius: 14px;
    display: flex; flex-wrap: wrap; gap: 8px 10px;
  }
  .page.rte ul.sea-jump li { margin: 0; }
  .page.rte ul.sea-jump a {
    display: inline-block; padding: 7px 14px; border-radius: 999px;
    background: #fff; border: 1px solid #e5e2dc; font-size: 14.5px;
    text-decoration: none; color: #1D3D3E;
  }
  .page.rte ul.sea-jump a:hover { background: #1D3D3E; color: #fff; border-color: #1D3D3E; }

  /* ---- responsive video ---------------------------------------------- */
  .page.rte iframe { width: 100%; max-width: 68ch; aspect-ratio: 16 / 9; height: auto; border-radius: 12px; }

  /* ---- sticky route to the offer ------------------------------------- */
  .sea-stick {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 40;
    background: #1D3D3E; color: #fff;
    transform: translateY(110%); transition: transform .28s ease;
    box-shadow: 0 -6px 24px rgba(0,0,0,.14);
  }
  .sea-stick.is-on { transform: translateY(0); }
  .sea-stick__in {
    max-width: 1100px; margin: 0 auto; padding: 12px 18px;
    display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  }
  .sea-stick__t { margin: 0; flex: 1 1 240px; font-size: 15px; line-height: 1.4; }
  .sea-stick__t b { font-weight: 600; }
  .sea-stick__a {
    flex: 0 0 auto; background: #D45A3C; color: #fff; text-decoration: none;
    padding: 11px 22px; border-radius: 999px; font-size: 15px; font-weight: 600;
  }
  .sea-stick__x {
    flex: 0 0 auto; background: none; border: 0; color: #fff; opacity: .7;
    font-size: 20px; line-height: 1; cursor: pointer; padding: 6px 4px;
  }
  .sea-stick__x:hover { opacity: 1; }
  @media (max-width: 599px) {
    .sea-stick__in { padding: 10px 14px; gap: 10px; }
    .sea-stick__t { flex-basis: 100%; font-size: 14px; }
    .sea-stick__a { flex: 1 1 auto; text-align: center; }
  }
  @media (prefers-reduced-motion: reduce) { .sea-stick { transition: none; } }
</style>

<div class="sea-stick" id="sea-stick" hidden>
  <div class="sea-stick__in">
    <p class="sea-stick__t"><b>Know the temperature. Now get fish worth cooking.</b> Lab-tested to &le; 0.1 ppm mercury.</p>
    <a class="sea-stick__a" href="/collections/all-seafood">Shop seafood</a>
    <button class="sea-stick__x" type="button" aria-label="Dismiss">&times;</button>
  </div>
</div>

<script>
  (function () {
    var rte = document.querySelector('.page.rte');
    if (rte) {
      // Tag the in-content anchor list so it reads as a jump nav, and wrap the
      // temperature table so it scrolls instead of squashing. Done in JS because
      // the markup lives in page.body and is not edited here.
      rte.querySelectorAll('ul').forEach(function (ul) {
        var links = ul.querySelectorAll('a[href^="#"]');
        if (links.length >= 3) ul.classList.add('sea-jump');
      });
      rte.querySelectorAll('table').forEach(function (t) {
        if (t.parentNode && t.parentNode.classList.contains('sea-table-scroll')) return;
        var w = document.createElement('div');
        w.className = 'sea-table-scroll';
        t.parentNode.insertBefore(w, t);
        w.appendChild(t);
      });
    }

    var bar = document.getElementById('sea-stick');
    if (!bar) return;
    try { if (sessionStorage.getItem('seaStickOff') === '1') return; } catch (e) {}
    bar.hidden = false;

    bar.querySelector('.sea-stick__x').addEventListener('click', function () {
      bar.classList.remove('is-on');
      try { sessionStorage.setItem('seaStickOff', '1'); } catch (e) {}
    });

    var shown = false;
    function onScroll() {
      var y = window.scrollY || document.documentElement.scrollTop;
      var h = document.documentElement.scrollHeight - window.innerHeight;
      var pct = h > 0 ? y / h : 0;
      // Appears once the reader is genuinely into the guide, and steps aside
      // near the foot so it never covers the offer sections.
      var want = pct > 0.12 && pct < 0.92;
      if (want !== shown) { shown = want; bar.classList.toggle('is-on', want); }
    }
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  })();
</script>

{%- comment -%}
  FAQPage structured data for the fish-temperature guide.

  Every question and answer below is copied VERBATIM from the visible page
  body. Google requires FAQ schema to match on-page content exactly; invented
  or paraphrased Q&A is a manual-action risk. If the body copy is edited in
  Shopify admin, this block MUST be updated to match or removed.

  The page previously had zero structured data despite carrying 9 genuine
  Q&A pairs — this is additive SEO, it changes nothing a visitor sees.
{%- endcomment -%}
<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is the cooking temperature for fish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The recommended cooking temperature for most fish is 145°F (63°C) when measured at the thickest part of the fish. However, certain fish like tuna, Hiramasa or Kanpachi can be served rare at 125°F (52°C)."
      }
    },
    {
      "@type": "Question",
      "name": "What is the temperature for cooking fish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fish should be cooked at varying temperatures depending on the method. For baking, an oven temperature of 350°F (175°C) is common. For frying, the oil should be between 350°F to 375°F (175°C to 190°C)."
      }
    },
    {
      "@type": "Question",
      "name": "What temperature is fish done?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fish is considered done when it reaches an internal temperature of 145°F (63°C) at its thickest part. The flesh should be opaque and flake easily with a fork. Remember, fish continues to cook a little bit when removed from the heat."
      }
    },
    {
      "@type": "Question",
      "name": "When is fish done temperature-wise?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "As mentioned, a fish is typically done when its internal temperature reads 145°F (63°C). However, personal preferences, or experimentation with rare or tataki preparation, might have different ideal temperatures."
      }
    },
    {
      "@type": "Question",
      "name": "What is the temperature for cooked fish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Once cooked, fish should have an internal temperature of 145°F (63°C) to ensure it's fully cooked. But this may not always be the goal! Some fish do best at lower temperatures, served medium rare or rare."
      }
    },
    {
      "@type": "Question",
      "name": "What temperature to fry fish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "When frying fish, the oil should be preheated to a temperature between 350°F to 375°F (175°C to 190°C) for optimal results."
      }
    },
    {
      "@type": "Question",
      "name": "What temperature should fish be cooked to?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "To reiterate, the safe and ideal internal temperature for most fish according to the FDA is 145°F (63°C). However, certain varieties like Ora King Salmon, kanpachi or hiramasa do well at lower internal temperatures if preferred."
      }
    },
    {
      "@type": "Question",
      "name": "What temperature is fish done in the oven?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "When baking fish in the oven, it's done when its fully cooked when its internal temperature reaches 145°F (63°C). This is usually achieved at an oven setting of around 350°F (175°C)."
      }
    },
    {
      "@type": "Question",
      "name": "What temperature is fish cooked?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A fish is considered cooked when its internal temperature is 145°F (63°C). It should have an opaque appearance and should flake easily, if fully cooked is the desired doneness."
      }
    }
  ]
}
</script>
